package com.eventfinder.dao;
import com.eventfinder.model.User; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.util.Optional;
@Repository public class UserDao {private final JdbcTemplate db;public UserDao(JdbcTemplate db){this.db=db;} public Optional<User> byEmail(String email){return db.query("SELECT id,name,email,role FROM users WHERE email=?",(r,n)->new User(r.getLong("id"),r.getString("name"),r.getString("email"),r.getString("role")),email).stream().findFirst();} public String password(String email){return db.queryForObject("SELECT password_hash FROM users WHERE email=?",String.class,email);} public User create(String name,String email,String hash){db.update("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'USER')",name,email,hash);return byEmail(email).orElseThrow();} }